-- G1 uses only scoped fixtures; every mutation and administrator replacement rolls back.
begin;
create function pg_temp.g_id(n integer) returns uuid language sql immutable as $$select ('d1000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create function pg_temp.g_assert(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;end$$;
create function pg_temp.g_error(statement text,state text) returns void language plpgsql as $$begin begin execute statement;exception when others then if sqlstate=state then return;end if;raise;end;raise exception 'Expected SQLSTATE %',state;end$$;
create function pg_temp.g_command(n integer default 0) returns jsonb language sql as $$select jsonb_build_object('commandId',pg_temp.g_id(n+1),'expectedVersion',0,'game',jsonb_build_object('id',pg_temp.g_id(n+2),'disputeId',pg_temp.g_id(92),'homeRegistrationId',pg_temp.g_id(95),'awayRegistrationId',pg_temp.g_id(96),'date',null,'time',null,'venue',null,'number',null))$$;
grant execute on function pg_temp.g_id(integer),pg_temp.g_assert(boolean,text),pg_temp.g_error(text,text),pg_temp.g_command(integer) to anon,authenticated,service_role;
delete from public.admin_access;
insert into auth.users(id) values(pg_temp.g_id(98)),(pg_temp.g_id(99));
insert into public.admin_access(user_id) values(pg_temp.g_id(98));
insert into public.championships(id,name) values(pg_temp.g_id(90),'G1 fixture');
insert into public.seasons(id,championship_id,year) values(pg_temp.g_id(91),pg_temp.g_id(90),2026);
insert into public.disputes(id,season_id,gender,category) values(pg_temp.g_id(92),pg_temp.g_id(91),'masculino','Adulto'),(pg_temp.g_id(93),pg_temp.g_id(91),'feminino','Adulto');
insert into public.teams(id,name) values(pg_temp.g_id(94),'One shared global team');
insert into public.registrations(id,dispute_id,team_id,name) values(pg_temp.g_id(95),pg_temp.g_id(92),pg_temp.g_id(94),'Team A'),(pg_temp.g_id(96),pg_temp.g_id(92),pg_temp.g_id(94),'Team B'),(pg_temp.g_id(97),pg_temp.g_id(93),pg_temp.g_id(94),'Other dispute');
set local role anon;
select pg_temp.g_error('select public.list_games(pg_temp.g_id(92))','42501');
select pg_temp.g_error('select public.save_game(pg_temp.g_command())','42501');
set local role authenticated;
set local request.jwt.claim.sub='d1000000-0000-4000-8000-000000000099';
select pg_temp.g_assert(public.get_game(pg_temp.g_id(2)) is null,'nonadmin cannot read');
select pg_temp.g_error('select public.save_game(pg_temp.g_command())','PT403');
set local request.jwt.claim.sub='d1000000-0000-4000-8000-000000000098';
select pg_temp.g_error('insert into public.games(id) values(pg_temp.g_id(2))','42501');
select pg_temp.g_error('select * from private.game_commands','42501');
create temp table g_before as select version,saved_at from public.championships where id=pg_temp.g_id(90);
select pg_temp.g_assert((public.save_game(pg_temp.g_command())->>'version')::int=1,'create game with two registrations of same global team');
select pg_temp.g_assert((public.save_game(pg_temp.g_command())->>'version')::int=1,'idempotent retry');
select pg_temp.g_assert((select count(*) from public.games where dispute_id=pg_temp.g_id(92))=1,'no duplicate');
select pg_temp.g_assert(public.get_game(pg_temp.g_id(2))->'date'='null'::jsonb and public.get_game(pg_temp.g_id(2))->'scheduledAt'='null'::jsonb and not(public.get_game(pg_temp.g_id(2)) ? 'score'),'no schedule/score fabrication');
select pg_temp.g_assert(public.get_game(pg_temp.g_id(2))->'home'->>'name'='Team A','registration public name');
select pg_temp.g_assert((select c.saved_at>b.saved_at and c.version=b.version from public.championships c cross join g_before b where c.id=pg_temp.g_id(90)),'save touches Recentes without changing the C1 document version');
select pg_temp.g_error($q$select public.save_game(jsonb_set(pg_temp.g_command(),'{game,venue}','"different"'))$q$,'PT409');
select pg_temp.g_error($q$select public.save_game(jsonb_set(pg_temp.g_command(),'{commandId}',to_jsonb(pg_temp.g_id(3))))$q$,'PT409');
-- Invalid contexts, same-side IDs, unknown fields and invalid schedules are atomic.
select pg_temp.g_error($q$select public.save_game(jsonb_set(pg_temp.g_command(10),'{game,awayRegistrationId}',to_jsonb(pg_temp.g_id(95))))$q$,'PT400');
select pg_temp.g_error($q$select public.save_game(jsonb_set(pg_temp.g_command(10),'{game,awayRegistrationId}',to_jsonb(pg_temp.g_id(97))))$q$,'PT400');
select pg_temp.g_error($q$select public.save_game(jsonb_set(pg_temp.g_command(10),'{game,date}','"2026-02-30"'))$q$,'PT400');
select pg_temp.g_error($q$select public.save_game(jsonb_set(pg_temp.g_command(10),'{game,time}','"15:30"'))$q$,'PT400');
select pg_temp.g_error($q$select public.save_game(jsonb_set(pg_temp.g_command(10),'{game,state}','"published"'))$q$,'PT400');
select pg_temp.g_assert(public.get_game(pg_temp.g_id(12)) is null,'invalid game leaves no partial record');
select pg_temp.g_assert((public.list_games(pg_temp.g_id(93))->'items')='[]'::jsonb,'disputes isolated');
select pg_temp.g_assert((public.list_games(pg_temp.g_id(92),'Team A')->'items'->0->>'id')=pg_temp.g_id(2)::text,'search includes sides');
select pg_temp.g_assert((public.list_games(pg_temp.g_id(92),'missing')->'items')='[]'::jsonb,'search filtering');
-- Explicit reload/version update succeeds; repeated stale intent still fails.
select public.save_game(jsonb_set(jsonb_set(jsonb_set(jsonb_set(pg_temp.g_command(),'{commandId}',to_jsonb(pg_temp.g_id(4))),'{expectedVersion}','1'),'{game,date}','"2026-10-23"'),'{game,time}','"15:30"'));
select pg_temp.g_assert((public.get_game(pg_temp.g_id(2))->>'scheduledAt')::timestamptz='2026-10-23T18:30:00Z'::timestamptz,'backend timezone conversion');
select pg_temp.g_assert(public.get_game(pg_temp.g_id(2))->>'time'='15:30','local time retained');
select pg_temp.g_error($q$select public.save_game(jsonb_set(jsonb_set(pg_temp.g_command(),'{commandId}',to_jsonb(pg_temp.g_id(5))),'{expectedVersion}','1'))$q$,'PT409');
select pg_temp.g_error($q$select public.save_game(jsonb_set(jsonb_set(pg_temp.g_command(),'{commandId}',to_jsonb(pg_temp.g_id(6))),'{expectedVersion}','1'))$q$,'PT409');
select pg_temp.g_assert((public.get_game(pg_temp.g_id(2))->>'version')::int=2,'stale writes did not recycle tokens');
select public.save_game(jsonb_set(pg_temp.g_command(30),'{game,date}','"2026-10-24"'));
select pg_temp.g_assert(public.get_game(pg_temp.g_id(32))->'scheduledAt'='null'::jsonb and public.get_game(pg_temp.g_id(32))->'time'='null'::jsonb,'date alone never invents midnight');
do $$begin for n in 1..20 loop perform public.save_game(pg_temp.g_command(200+n*10));end loop;end$$;
select pg_temp.g_assert(jsonb_array_length(public.list_games(pg_temp.g_id(92))->'items')=20 and (public.list_games(pg_temp.g_id(92))->>'hasMore')::boolean,'bounded first page');
select pg_temp.g_assert(jsonb_array_length(public.list_games(pg_temp.g_id(92),'',20)->'items')=2 and not (public.list_games(pg_temp.g_id(92),'',20)->>'hasMore')::boolean,'next page preserves remaining games');
select pg_temp.g_error($q$select public.save_game(jsonb_set(jsonb_set(jsonb_set(pg_temp.g_command(),'{commandId}',to_jsonb(pg_temp.g_id(7))),'{expectedVersion}','2'),'{game,disputeId}',to_jsonb(pg_temp.g_id(93))))$q$,'PT400');
delete from g_before;insert into g_before select version,saved_at from public.championships where id=pg_temp.g_id(90);
select public.get_game(pg_temp.g_id(2));select public.list_games(pg_temp.g_id(92));
select pg_temp.g_assert((select c.version=b.version and c.saved_at=b.saved_at from public.championships c cross join g_before b where c.id=pg_temp.g_id(90)),'reads do not touch Recentes');
reset role;
update public.admin_access set enabled=false;
set local role authenticated;
select pg_temp.g_assert(public.get_game(pg_temp.g_id(2)) is null,'revoked admin loses reads');
select pg_temp.g_error('select public.save_game(pg_temp.g_command())','PT403');
set local role service_role;
select pg_temp.g_error('select public.get_game(pg_temp.g_id(2))','42501');
reset role;
select pg_temp.g_assert((select relrowsecurity from pg_class where oid='public.games'::regclass),'games RLS');
rollback;
